#include "stdafx.h"#include "ServerExPlugin_Honey.h"#include <enumquerytypes.h>#include <CommonH.h>#include <macros/AutoCloser.h>#include <_alarmentry.h>#include <serverexplugintypes.h>extern "C" SERVEREXPLUGIN_HONEY5XX_API DWORD AlarmsSupport( BYTE **buffer, int &sizeReq, DWORD rsuID, tMemReallocer pMemR ){  DWORD size = 0;  if( id_Rsu_HoneyWell5xx != rsuID )    return size;  BYTE *pRequest = *buffer;  QueryTypes qType = *(QueryTypes*) pRequest;  int* N = (int*)(pRequest + sizeof(QueryTypes));  FILETIME fileCreation,fileLastWrite;  KAutoCloser<HANDLE> hHandle( ::CreateFile( GetAlarmFileName( (N[2]%2) == 1 ),                                            GENERIC_READ|GENERIC_WRITE,                                            FILE_SHARE_READ|FILE_SHARE_WRITE,                                            NULL,                                            OPEN_ALWAYS,                                            FILE_ATTRIBUTE_NORMAL,                                            NULL ),                               ::CloseHandle );  if ( hHandle != INVALID_HANDLE_VALUE)   {    if( !GetFileTime(hHandle, &fileCreation, NULL, &fileLastWrite) )      return size;  }  //  OVERLAPPED Overlapped = {0,0,N[0]*sizeof(CAlarmEntry),0,0};  DWORD nReadBytes      =      N[1]*sizeof(CAlarmEntry);  DWORD nBytesRead;  // Используем в качестве выходного буфера - входной  *buffer = pMemR( *buffer, nReadBytes, sizeReq );  BOOL bResult = ReadFile( hHandle, *buffer, nReadBytes, &nBytesRead, &Overlapped );  if ( bResult && nReadBytes == nBytesRead )    return nBytesRead;  return size;}